import json,re
root=Path(__file__).resolve().parents[1]
def clean(x):
 if isinstance(x,str):return re.sub(r'\\\\(?=[A-Za-z])',lambda m:'\\',x)
 if isinstance(x,list):return [clean(v) for v in x]
 if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
 return x
R=clean({n:json.loads((root/'readers'/n/'scan009.json').read_text()) for n in ['R1','R2','R3']})
T={n:(root/'readers'/n/'scan009.tex').read_text() for n in R}
final=T['R2']
def replace(old,new,count=1):
 global final
 assert old in final,old
 final=final.replace(old,new,count)
replace(r'\unsure{M|\mathcal M}',r' M')
replace(r'\deleted{\unsure{\parallel}}',r'\deleted{\parallel}')
