heavy=r'\mathrel{\tikz[baseline=-.4ex,x=.65em,y=.65em,line cap=round]{\draw (0,1.1)--(1,.5)--(0,-.1) (1,1.1)--(0,.5)--(1,-.1);\draw[line width=.95pt] (.14,.62)--(.85,.65)--(.13,.26)--(.9,.12) (.91,.96)--(.12,.34)--(.78,.31)--(.1,-.16);}}'
replace("F'_{L}"+plain+"G'_{L}","F'_{L}"+heavy+"G'_{L}")

