# not. Drawing it avoids choosing an unsupported word or punctuation identity.
sep=r'\mathrel{\tikz[baseline=-.3ex,x=.48em,y=.65em,line cap=round]{\draw (.4,.9)..controls(-.05,.8)and(-.08,.04)..(.35,.04)..controls(.66,.04)and(.6,.6)..(.3,.63);\draw (.43,.33)--(.66,.35) (.33,.03)--(.36,-.1);}}'
replace(r'\unsure{o|,}',sep)
