final=final[:ms]+final[me:]
ds=final.index(r'\deleted{\uline{At} DC 1')
fs=final.index('% Shallow enclosing contour')
fe=final.index('\\end{tikzpicture}}',fs)+len('\\end{tikzpicture}}')
old=final[ds:fs].strip()
frame=final[fs:fe]
at2=frame.split('(draft) at (0,0) {',1)[1].split('};\n\\draw',1)[0]
